+
+  /** Set playback speed multiplier (0.5–4). Takes effect immediately. */
+  setSpeed(multiplier: number): void {
+    this._speed = Math.min(4, Math.max(0.5, multiplier));
+  }
+
+  /** Pause event playback. */
+  pause(): void {
+    this._paused = true;
+  }
+
+  /** Resume event playback. */
+  resume(): void {
+    if (this._paused) {
+      this._paused = false;
+      this._scheduleNext();
+    }
+  }
