+    const removedEdge = GRAPH.edges.find(
+      (e) => e.from === 'be:field:Order.cust_id' && e.type === 'MAPS_TO'
+    );
+    const addedEdge: GraphEdge = removedEdge
+      ? { ...removedEdge, from: 'be:field:Order.customer_id' }
+      : {
